// src/core/queue.ts
var queue = new PQueue({ concurrency: 2 });
var geoipQueue = {
  async add(data) {
    logger3.trace({ data }, "Adding GeoIP job to queue");
    await queue.add(async () => {
      try {
        logger3.info({ nodeId: data.nodeId, ip: data.ip }, "Starting GeoIP lookup");
        const location2 = await getGeoLocation(data.ip);
        logger3.info({ nodeId: data.nodeId, location: location2 }, "Got location data");
        if (location2) {
          logger3.info({ nodeId: data.nodeId }, "Calling nodeService.updateGeoLocation");
          const result = await nodeService.updateGeoLocation(data.nodeId, location2);
          logger3.info({ nodeId: data.nodeId, result }, "Database update result");
        } else {
          logger3.warn({ nodeId: data.nodeId, ip: data.ip }, "No location data returned - GeoIP database may be missing");
        }
        logger3.info({ nodeId: data.nodeId, location: location2 }, "GeoIP job completed");
      } catch (error53) {
        logger3.error({ error: error53, nodeId: data.nodeId }, "GeoIP job failed");
        throw error53;
      }
    });
  }
};
process.on("SIGINT", async () => {
  logger3.info("Waiting for GeoIP queue to finish...");
  await queue.onIdle();
  process.exit(0);
});

// src/features/kaja/routes/node/connect.ts
var connectRoute = createRoute({
  method: "post",
  path: "/connect",
  tags: ["Nodes"],
  summary: "Connect a CLI node",
  description: "Register or reconnect a CLI node to the API",
  security: [{ bearerAuth: [] }],
  request: {
    body: {
      content: {
        "application/json": {
          schema: connectNodeRequestSchema
        }
      }
    }
  },
  responses: {
    200: {
      description: "Node connected successfully",
      content: {
        "application/json": {
          schema: connectNodeResponseSchema
        }
      }
    },
    401: {
      description: "Unauthorized",
      content: {
        "application/json": {
          schema: { type: "object", properties: { error: { type: "string" } } }
        }
      }
    }
  }
});
function registerConnect(app) {
  app.openapi(connectRoute, async (c2) => {
    const user = c2.get("user");
    if (!user) {
      return unauthorized(c2);
    }
    const body = c2.req.valid("json");
    const nodeService2 = c2.get("nodeService");
    const nodeId = Bun.randomUUIDv7();
    await nodeService2.connectNode({
      id: nodeId,
      userId: user.id,
      name: body.name
    });
    const clientIp = getClientIp(c2);
    if (clientIp) {
      logger3.info({ ip: clientIp, nodeId }, "Queueing GeoIP lookup");
      geoipQueue.add({ ip: clientIp, nodeId }).catch((error53) => {
        logger3.error({ error: error53, nodeId, ip: clientIp }, "Failed to queue GeoIP lookup");
      });
      logger3.info({ ip: clientIp, nodeId }, "Queued GeoIP lookup");
    } else {
      logger3.warn({ nodeId }, "Could not get public IP address for GeoIP lookup");
    }
    return c2.json(connectNodeResponseSchema.parse({
      nodeId,
      pollIntervalMs: 2000
    }));
  });
}

