// src/features/kaja/routes/node/heartbeat.ts
var NORMAL_POLL_INTERVAL = 60000;
var FAST_POLL_INTERVAL = 5000;
var heartbeatRoute = createRoute({
  method: "post",
  path: "/heartbeat",
  tags: ["Nodes"],
  summary: "Update node heartbeat",
  description: "Send heartbeat with node status and optionally receive pending commands",
  security: [{ bearerAuth: [] }],
  request: {
    body: {
      content: {
        "application/json": {
          schema: heartbeatRequestSchema
        }
      }
    }
  },
  responses: {
    200: {
      description: "Heartbeat accepted",
      content: {
        "application/json": {
          schema: heartbeatResponseSchema
        }
      }
    },
    401: {
      description: "Unauthorized",
      content: {
        "application/json": {
          schema: { type: "object", properties: { error: { type: "string" } } }
        }
      }
    },
    404: {
      description: "Unknown node",
      content: {
        "application/json": {
          schema: { type: "object", properties: { error: { type: "string" } } }
        }
      }
    }
  }
});
function registerHeartbeat(app) {
  app.openapi(heartbeatRoute, async (c2) => {
    const user = c2.get("user");
    if (!user) {
      return unauthorized(c2);
    }
    const body = c2.req.valid("json");
    const nodeService2 = c2.get("nodeService");
    const commandService = c2.get("commandService");
    const success2 = await nodeService2.heartbeat(body.nodeId, user.id, body.status);
    if (!success2) {
      return notFound(c2, "Unknown node");
    }
    if (body.commandResults && body.commandResults.length > 0) {
      for (const result of body.commandResults) {
        await commandService.updateCommandResult(result.commandId, result);
      }
    }
    const pendingCommands = await commandService.getPendingCommands(body.nodeId);
    for (const cmd of pendingCommands) {
      await commandService.markCommandExecuting(cmd.commandId);
    }
    const hasPendingCommands = pendingCommands.length > 0;
    const pollIntervalMs = hasPendingCommands ? FAST_POLL_INTERVAL : NORMAL_POLL_INTERVAL;
    return c2.json(heartbeatResponseSchema.parse({
      ok: true,
      pollIntervalMs,
      commands: pendingCommands.length > 0 ? pendingCommands : undefined
    }));
  });
}

