// src/features/kaja/routes/node/stream.ts
function registerStream(app) {
  app.get("/nodes/stream", async (c2) => {
    const user = c2.get("user");
    if (!user) {
      return c2.json({ error: "Unauthorized" }, 401);
    }
    const userId = user.id;
    return streamSSE(c2, async (stream2) => {
      logger3.info({ userId }, "SSE client connected");
      await stream2.writeSSE({
        data: JSON.stringify({ type: "connected" }),
        event: "node-update"
      });
      const eventHandler = async (event) => {
        if (event.userId === userId) {
          await stream2.writeSSE({
            data: JSON.stringify({
              type: event.type,
              node: {
                id: event.node.id,
                userId: event.node.userId,
                name: event.node.name,
                lastSeen: event.node.lastSeen.toISOString(),
                status: event.node.status
              }
            }),
            event: "node-update"
          });
        }
      };
      nodeEvents.on("node-update", eventHandler);
      const pingInterval = setInterval(async () => {
        await stream2.writeSSE({
          data: JSON.stringify({ type: "ping" }),
          event: "ping"
        });
      }, 30000);
      stream2.onAbort(() => {
        logger3.info({ userId }, "SSE client disconnected");
        nodeEvents.off("node-update", eventHandler);
        clearInterval(pingInterval);
      });
      while (true) {
        await stream2.sleep(30000);
      }
    });
  });
}

